#include <cstdio>
#include <vector>
#include <cstring>

const int MAXN=60;
const int MOD=1000000007;
long long n;
int k;

inline int add(int x){return x>=MOD?x-MOD:x;}
inline int sub(int x){return x<0?x+MOD:x;}
inline int mul(int x,int y){return (long long)x*y%MOD;}

struct Matrix {
    int a[MAXN][MAXN];
    int size;
    void clear() { memset(a,0,sizeof(a)); }
    void identity() {
        clear();
        for(int i=1;i<=size;i++){a[i][i]=1;}
    }
    Matrix operator *(const Matrix& rhs) const {
        Matrix res; res.size= size;
        long long tmp[MAXN][MAXN]; memset(tmp,0,sizeof(tmp));
        LL MODLL= (LL)MOD*MOD;
        for (int i=1;i<=size;++i) {
            for (int j=1;j<=size;++j){
                for (int k=1;k<=size;++k) {
                    tmp[i][j]+=(LL)a[i][k]*rhs.a[k][j];
                    if(tmp[i][j]>=MODLL) tmp[i][j]-=MODLL;
                }
            }
        }
        for (int i=1;i<=size;++i)
            for (int j=1;j<=size;++j)
                res.a[i][j]=tmp[i][j]%MOD;
        return res;
    }
};

std::vector<std::vector<Matrix>> f,sump,sums;
std::vector<int> num;
int cnt;

void run() {
    num.clear(); f.clear(); sump.clear(); sums.clear();
    for (long long x=n; x>0; x/=k) {
        num.push_back(x%k);
    }
    cnt= (int)num.size();

    f.resize(cnt, std::vector<Matrix>(k));
    sump.resize(cnt, std::vector<Matrix>(k));
    sums.resize(cnt, std::vector<Matrix>(k));

    for (int i=0; i<cnt; i++){
        for(int j=0; j<k; j++){
            f[i][j].size=k+1; f[i][j].clear(); f[i][j].identity();
            for(int t=1; t<=k+1; t++){
                f[i][j].a[t][t]=1;
            }
            for(int t=1; t<=k+1; t++){
                f[i][j].a[i+1][t]=1;
            }
        }
    }

    for (int j=0; j<k; j++){
        sump[0][j]=f[0][j];
    }

    for (int i=1; i<cnt; i++){
        for (int j=0;j<k;j++){
            int idx= (j==0)?0:j;
            f[i][j]= (j==0)?sums[i-1][j]:sump[i-1][j-1]*sums[i-1][j];
        }
        for (int j=0; j<k; j++){
            if(j==0) sump[i][j]=f[i][j];
            else sump[i][j]=f[i][j]*sump[i][j-1];
        }
        for(int j=k-2;j>=0;j--){
            sums[i][j]=sums[i][j+1]*f[i][j];
        }
    }

    Matrix ans; ans.size=k+1; ans.identity();

    int sumCount=0;
    for(int i=cnt-1;i>=0;i--) {
        for(int j=0;j<num[i];j++){
            int idx=(sumCount+j)%k;
            ans=f[i][idx]*ans;
        }
        sumCount+=num[i]; sumCount%=k;
    }

    int res=0;
    for(int i=1;i<=k+1;i++){
        res=add(res+ans.a[i][k+1]);
    }
    printf("%d\n", res);
}

int main() {
    scanf("%lld %d",&n,&k);
    run();
}
